tap_q = asyncio.Queue(maxsize=1024)

class Tap:
    def __init__(self, primary_q):
        self.primary_q, self.drops = primary_q, 0

    async def forward(self, msg):
        try:
            tap_q.put_nowait(copy.deepcopy(msg))   # independent copy
        except asyncio.QueueFull:
            self.drops += 1                        # counted drop, never blocks
        await self.primary_q.put(msg)              # original, unchanged

async def analyzer():
    while True:
        await asyncio.to_thread(inspect, await tap_q.get())  # off the loop
